// REQ-SDC-02/03/05/06/07 contract tests (SDP-2.1 §7.3): every request the JS client sends and
// every response it understands is checked against the JSON Schema exported by gwb-sidecar-api
// (sidecar/schema/api.schema.json, regenerated by `cargo run -p gwb-sidecar-api --bin export-schema`).
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { SidecarClient, ndjson, profileForName, PORTS, LOOPBACK_ORIGINS, isLoopbackOrigin } from '../../app/src/sidecar/client.js';
import { NetLog, isSidecarOrigin } from '../../app/src/ai/netlog.js';

const SCHEMA = JSON.parse(readFileSync(new URL('../../sidecar/schema/api.schema.json', import.meta.url), 'utf8'));
const ORIGINS = JSON.parse(readFileSync(new URL('../../build/origins.json', import.meta.url), 'utf8'));

/** A validator for the JSON Schema subset schemars emits (type, enum, const, $ref/$defs, oneOf/anyOf, items, required, additionalProperties, min/max). */
function validate(schema, value, root = schema, path = '$') {
  const errs = [];
  const s = schema.$ref ? resolveRef(root, schema.$ref) : schema;
  const type = (v) => (v === null ? 'null' : Array.isArray(v) ? 'array' : Number.isInteger(v) ? 'integer' : typeof v);
  const is = (t, v) => t === type(v) || (t === 'number' && typeof v === 'number');
  if (s.oneOf) {
    const ok = s.oneOf.filter((x) => validate(x, value, root, path).length === 0).length;
    if (ok !== 1) errs.push(`${path}: matches ${ok} of oneOf`);
    return errs;
  }
  if (s.anyOf) {
    if (!s.anyOf.some((x) => validate(x, value, root, path).length === 0)) errs.push(`${path}: matches none of anyOf`);
    return errs;
  }
  if (s.const !== undefined && value !== s.const) errs.push(`${path}: ${JSON.stringify(value)} ≠ ${JSON.stringify(s.const)}`);
  if (s.enum && !s.enum.includes(value)) errs.push(`${path}: ${JSON.stringify(value)} not in ${s.enum}`);
  if (s.type) {
    const ts = [].concat(s.type);
    if (!ts.some((t) => is(t, value))) return [`${path}: ${type(value)} is not ${ts.join('|')}`];
  }
  if (typeof value === 'number') {
    if (s.minimum !== undefined && value < s.minimum) errs.push(`${path}: below ${s.minimum}`);
    if (s.maximum !== undefined && value > s.maximum) errs.push(`${path}: above ${s.maximum}`);
  }
  if (Array.isArray(value) && s.items) value.forEach((v, i) => errs.push(...validate(s.items, v, root, `${path}[${i}]`)));
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    for (const r of s.required ?? []) if (!(r in value)) errs.push(`${path}: missing ${r}`);
    for (const [k, v] of Object.entries(value)) {
      if (s.properties?.[k]) errs.push(...validate(s.properties[k], v, root, `${path}.${k}`));
      else if (s.additionalProperties === false) errs.push(`${path}: unknown field ${k}`);
      else if (typeof s.additionalProperties === 'object') errs.push(...validate(s.additionalProperties, v, root, `${path}.${k}`));
    }
  }
  return errs;
}
function resolveRef(root, ref) {
  const name = ref.replace('#/$defs/', '');
  return root.$defs?.[name] ?? SCHEMA.types[name] ?? (() => { throw new Error(`unresolved ${ref}`); })();
}
const check = (type, value) => validate(SCHEMA.types[type], value, SCHEMA.types[type]);

const BASE = 'http://127.0.0.1:47821';
const T = 'a'.repeat(64);
const job = (o = {}) => ({ id: 'b'.repeat(24), profile: 'raster-cog', state: 'queued', progress: null, inputs: ['c'.repeat(32)], outputs: [], created: '2026-11-01T12:00:00Z', ...o });

/** A fake sidecar: validates each request body against its schema and answers schema-valid JSON. */
function fakeSidecar({ paired = true } = {}) {
  const seen = [];
  const routes = [
    ['GET', /\/v1\/hello$/, () => [200, { service: 'gwb-sidecar', version: '0.1.0', api: 1, port: 47821, paired, origin: 'null', channel: 'preview' }, 'Hello']],
    ['POST', /\/v1\/pair$/, (b) => (seen.push(check('PairRequest', b)), [200, { pairing_id: 'd'.repeat(48), code: '042917', expires_in: 180 }, 'PairStart'])],
    ['GET', /\/v1\/pair\/d+$/, () => [200, { state: 'approved', token: T }, 'PairStatus']],
    ['POST', /\/v1\/jobs$/, (b) => (seen.push(check('JobRequest', b)), [201, job({ profile: b.profile, inputs: b.inputs }), 'Job'])],
    ['GET', /\/v1\/jobs\/b+$/, () => [200, job({ state: 'succeeded', progress: 1, outputs: [{ id: 'e'.repeat(32), name: 'x.cog.tif', size: 10, origin: 'output' }] }), 'Job']],
    ['POST', /\/v1\/pick$/, (b) => (seen.push(check('PickRequest', b)), [200, { files: [{ id: 'f'.repeat(32), name: 'Hamilton.sid', size: 10_700_000_000, origin: 'pick' }] }, 'PickResult'])],
    ['POST', /\/v1\/batch$/, (b) => (seen.push(check('BatchRequest', b)), [201, { jobs: [job()] }, 'BatchResult'])],
    ['PUT', /\/v1\/files\?/, () => [201, { id: 'c'.repeat(32), name: 'x.sid', size: 3, origin: 'upload', group: '1'.repeat(24) }, 'FileInfo']],
    ['DELETE', /\/v1\/pair$/, () => [204, null]],
    ['POST', /\/v1\/views$/, (b) => (seen.push(check('ViewRequest', b)), [201, { id: '7'.repeat(24), name: 'Hamilton.sid', driver: 'MrSID', size: 412_000_000_000, width: 340000, height: 220000, bands: 3, sample_type: 'Byte', levels: 11, tile: 512 }, 'ViewInfo'])],
    ['DELETE', /\/v1\/views\/7+$/, () => [204, null]],
  ];
  const fetch = async (url, init = {}) => {
    const method = init.method ?? 'GET';
    const route = routes.find(([m, re]) => m === method && re.test(url));
    if (!route) return new Response(JSON.stringify({ code: 'not_found', error: 'no' }), { status: 404 });
    const body = typeof init.body === 'string' ? JSON.parse(init.body) : undefined;
    if (body !== undefined) expect(init.headers['Content-Type']).toBe('application/json');
    const [status, json, type] = route[2](body);
    if (type) expect(check(type, json), `${type} sample`).toEqual([]);
    seen.push({ method, url, auth: init.headers?.Authorization ?? null });
    return new Response(json === null ? null : JSON.stringify(json), { status, headers: { 'content-type': 'application/json' } });
  };
  return { fetch, seen };
}
const memStore = () => ({ v: null, get: async function () { return this.v; }, set: async function (x) { this.v = x; }, clear: async function () { this.v = null; } });

describe('sidecar client against the API schema', () => {
  it('the schema lists the API level and ports the client uses', () => {
    expect(SCHEMA.api).toBe(1);
    expect(SCHEMA.ports).toEqual(PORTS);
    for (const t of ['Hello', 'PairRequest', 'PairStart', 'PairStatus', 'Caps', 'JobRequest', 'Job', 'JobEvent', 'PickRequest', 'FileInfo', 'ErrorBody']) expect(SCHEMA.types[t], t).toBeTruthy();
  });

  it('discovers, pairs and sends only schema-valid requests', async () => {
    const { fetch, seen } = fakeSidecar({ paired: false });
    const c = new SidecarClient({ fetch, store: memStore() });
    const hello = await c.discover();
    expect(hello.service).toBe('gwb-sidecar');
    expect(c.base).toBe(BASE);
    let code = null;
    const sc2 = fakeSidecar({ paired: true });
    // After approval the next hello says paired.
    c.fetch = async (u, i) => (/hello$/.test(u) && code ? sc2.fetch(u, i) : fetch(u, i));
    await c.pair({ client: 'GIS Workbench test', onCode: (x) => (code = x), interval: 1 });
    expect(code).toBe('042917');
    expect(c.token).toBe(T);
    expect(c.paired).toBe(true);
    const errs = seen.filter(Array.isArray).flat();
    expect(errs).toEqual([]);
  });

  it('waits longer for the sidecar it already knows (busy with a job) than for an unknown port', async () => {
    const { fetch } = fakeSidecar({ paired: true });
    const slow = (ms) => async (u, i) => {
      await new Promise((r, x) => {
        const t = setTimeout(r, ms);
        i?.signal?.addEventListener('abort', () => (clearTimeout(t), x(new DOMException('aborted', 'AbortError'))));
      });
      return fetch(u, i);
    };
    const known = new SidecarClient({ fetch: slow(400), store: memStore(), base: BASE });
    expect((await known.discover({ timeout: 100 }))?.service).toBe('gwb-sidecar');
    const fresh = new SidecarClient({ fetch: slow(400), store: memStore() });
    expect(await fresh.discover({ timeout: 100 })).toBe(null);
  });

  it('jobs, picks and batches validate; every call carries the bearer token', async () => {
    const { fetch, seen } = fakeSidecar();
    const c = new SidecarClient({ fetch, store: memStore(), base: BASE });
    c.token = T;
    await c.createJob({ profile: 'raster-cog', inputs: ['c'.repeat(32)], options: { compress: 'DEFLATE', quality: 85 }, reason: 'refused by the app' });
    await c.createJob({ profile: 'export-ogr', inputs: ['c'.repeat(32)], options: { driver: 'MapInfo File', lco: ['ENCODING=UTF-8'] } });
    await c.pick('file', 'Choose');
    await c.pick('folder');
    await c.batch({ profile: 'raster-cog', folder: 'f'.repeat(32), extensions: ['sid'], options: {} });
    const up = await c.upload(new Blob(['abc']), { name: 'x.sid' });
    expect(check('FileInfo', up)).toEqual([]);
    const j = await c.job('b'.repeat(24));
    expect(j.outputs[0].name).toBe('x.cog.tif');
    expect(seen.filter(Array.isArray).flat()).toEqual([]);
    for (const r of seen.filter((x) => !Array.isArray(x))) expect(r.auth).toBe(`Bearer ${T}`);
    // A request with an unknown field is what the schema (and the service) refuse.
    expect(check('JobRequest', { profile: 'raster-cog', inputs: [], shell: 'cmd' })).not.toEqual([]);
    expect(check('PickRequest', { mode: 'drive' })).not.toEqual([]);
  });

  it('views: opened and closed by schema-valid calls, read through the signer (REQ-GAP-70)', async () => {
    const f = fakeSidecar();
    const c = new SidecarClient({ fetch: f.fetch, store: memStore(), base: BASE });
    c.token = T;
    const v = await c.openView('f'.repeat(32));
    expect(v.tile).toBe(512);
    expect(c.viewUrl(v.id)).toBe(`${BASE}/v1/views/${'7'.repeat(24)}`);
    await c.closeView(v.id);
    expect(f.seen.filter(Array.isArray).flat()).toEqual([]);
    expect(check('ViewRequest', { file: 'x', path: 'C:/secret.sid' }).length).toBeGreaterThan(0);
    expect(f.seen.filter((x) => x.method).every((x) => x.auth === `Bearer ${T}`)).toBe(true);
  });

  it('remote reads of results are signed with the token', async () => {
    const c = new SidecarClient({ fetch: async () => new Response(''), store: memStore(), base: BASE });
    c.token = T;
    const s = await c.signer()(`${BASE}/v1/files/x`, { headers: { Range: 'bytes=0-0' } });
    expect(s.init.headers).toEqual({ Range: 'bytes=0-0', Authorization: `Bearer ${T}` });
  });

  it('reads NDJSON events split anywhere, skipping keep-alives, ending at done', async () => {
    const events = [{ type: 'state', state: 'running' }, { type: 'progress', progress: 0.25 }, { type: 'log', line: 'x "q" ✓' }, { type: 'done', job: job({ state: 'succeeded', progress: 1 }) }];
    for (const e of events) expect(check('JobEvent', e), JSON.stringify(e)).toEqual([]);
    expect(check('JobEvent', { type: 'progress' })).not.toEqual([]);
    const text = `${events.slice(0, 2).map((e) => JSON.stringify(e)).join('\n')}\n\n\n${events.slice(2).map((e) => JSON.stringify(e)).join('\n')}\n{"type":"log","line":"after done"}\n`;
    const bytes = new TextEncoder().encode(text);
    const chunks = [];
    for (let i = 0; i < bytes.length; i += 7) chunks.push(bytes.slice(i, i + 7));
    const stream = new ReadableStream({ start(c) { chunks.forEach((x) => c.enqueue(x)); c.close(); } });
    const got = [];
    for await (const e of ndjson(stream)) got.push(e);
    expect(got).toEqual(events);
  });

  it('maps refused files to their conversion profile', () => {
    expect(profileForName('Hamilton_2023.sid')).toBe('raster-cog');
    expect(profileForName('x.ECW')).toBe('raster-cog');
    expect(profileForName('parcels.gdb.zip')).toBe('vector-gpkg');
    expect(profileForName('scan.e57')).toBe('points-copc');
    expect(profileForName('uav.ts')).toBe('video-h264-klv');
    expect(profileForName('collect.cphd')).toBe(null);
    expect(profileForName('photo.heic')).toBe(null);
  });
});

describe('loopback origins (REQ-SDC-02, REQ-SDC-14)', () => {
  it('origins.json, the client and NetLog agree on the three ports', () => {
    expect(ORIGINS.loopback.origins).toEqual(LOOPBACK_ORIGINS);
    for (const o of LOOPBACK_ORIGINS) expect(isSidecarOrigin(o) && isLoopbackOrigin(o)).toBe(true);
    for (const o of ['http://127.0.0.1:47824', 'http://localhost:47821', 'https://127.0.0.1:47821', 'http://127.0.0.1']) expect(isSidecarOrigin(o)).toBe(false);
  });

  it('loopback calls pass while Offline, are logged, and stop when the Sidecar switch is off', async () => {
    let on = true;
    const app = { network: { isOnline: () => false, airgap: true }, sidecar: { enabled: () => on }, emit() {} };
    const log = new NetLog(app);
    globalThis.document = { getElementById: () => ({ getAttribute: () => `default-src 'none'; connect-src blob: ${LOOPBACK_ORIGINS.join(' ')}` }) };
    const real = globalThis.fetch;
    globalThis.fetch = async () => new Response('{}', { status: 200 });
    try {
      const f = log.fetchFor('sidecar');
      const r = await f(`${LOOPBACK_ORIGINS[0]}/v1/hello`);
      expect(r.status).toBe(200);
      expect(log.entries[0]).toMatchObject({ origin: LOOPBACK_ORIGINS[0], status: 200, loopback: true, purpose: 'sidecar' });
      // Any other origin is still blocked offline.
      await expect(f('https://example.org/x')).rejects.toThrow(/air-gapped|offline/);
      on = false;
      await expect(f(`${LOOPBACK_ORIGINS[1]}/v1/hello`)).rejects.toThrow(/Sidecar switch is off/);
      expect(log.entries[0]).toMatchObject({ status: 'sidecar off' });
    } finally {
      globalThis.fetch = real;
      delete globalThis.document;
    }
  });
});
